o=ROOT/"phase80";pr=json.loads((o/"protocol.json").read_text());assert (o/"complete.json").exists();ex=json.loads((o/"execution_audit.json").read_text());assert ex["status"]=="PASS";rows=[];maxprotoerr=0.;memory=[]
