 key=f'{spec["model"]}_seed{spec["seed"]}';head=np.load(o/"cache"/(key+"_head.npz"));w=head["weight"].astype(float);b=head["bias"].astype(float);warm_labels=(w@w.T+b).argmax(1);labels=np.eye(5)[warm_labels];wn=w/np.maximum(np.linalg.norm(w,axis=1,keepdims=True),1e-12);weights=wn.T@labels;weights/=np.maximum(np.linalg.norm(weights,axis=0,keepdims=True),1e-12)
