   a=np.load(o/"predictions"/f"{key}_s{sid:02d}_{mode}.npz");cache=np.load(o/"cache"/f"{key}_s{sid:02d}_{mode}.npz");z=cache["z"];assert np.array_equal(a["frozen"],cache["p"]);reference=softmax(z.astype(float)@weights,axis=1);reference[0]=a["frozen"][0];err=float(abs(reference-a["source_prototype_static"]).max());maxprotoerr=max(maxprotoerr,err);assert err<3e-5
   ids=a["final_ids"];assert len(ids)==len(set(ids.tolist())) and ((ids>=-5)&(ids<len(y))).all();reconstructed=np.stack([head["weight"][i+5] if i<0 else z[i] for i in ids]);assert np.array_equal(reconstructed,a["final_supports"]);expected_labels=np.array([warm_labels[i+5] if i<0 else cache["p"][i].argmax() for i in ids]);assert np.array_equal(expected_labels,a["final_labels"].argmax(1));tr=a["trace"];assert (tr[:,2:]<=20).all() and np.array_equal(tr[:,2:].sum(1),tr[:,0]) and tr[-1,0]==len(ids);memory.append(dict(model=key,subject=sid,input_mode=mode,mean_supports=float(tr[:,0].mean()),retained_current_fraction=float(tr[:,1].mean()),final_supports=len(ids)))
   for method in pr["methods"]:
    p=a[method];assert p.shape==(len(y),5) and np.isfinite(p).all() and abs(p.sum(1)-1).max()<2e-6 and np.array_equal(p[0],a["frozen"][0])
    for smooth in pr["ema"]:
     q=p if smooth==1 else ema(p,smooth);m=metrics(y,q);cm=np.array(m["confusion"]);rows.append(dict(subject=sid,model=spec["model"],seed=spec["seed"],input_mode=mode,method=method,ema=smooth,macro_f1=100*m["macro_f1"],accuracy=100*cm.trace()/cm.sum(),ce=m["ce"]))
